fn cache_non_readonly_decision(
    permission_manager: &PermissionManager,
    candidate: &ToolRequest,
    is_readonly: bool,
) {
    if is_readonly {
        return;
    }
    if let Ok(tool_call) = &candidate.tool_call {
        permission_manager
            .update_smart_approve_permission(&tool_call.name, PermissionLevel::AskBefore);
    }
}

